<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';const code=ref(''),recent=ref<string[]>(JSON.parse(localStorage.getItem('voltbridge.recentDevices')||'[]')),router=useRouter();function go(){const c=code.value.trim();if(!c)return;recent.value=[c,...recent.value.filter(x=>x!==c)].slice(0,8);localStorage.setItem('voltbridge.recentDevices',JSON.stringify(recent.value));router.push(`/devices/${encodeURIComponent(c)}`)}</script>
<template><div class="page"><h1>Device lookup</h1><el-card><el-form inline @submit.prevent="go"><el-form-item label="Device code"><el-input v-model="code" placeholder="Enter device code" @keyup.enter="go"/></el-form-item><el-button type="primary" @click="go">Look up device</el-button></el-form><el-empty description="The backend supports lookup by device code, not a full inventory."/><template v-if="recent.length"><h3>Recent Lookups · local history</h3><el-tag v-for="c in recent" :key="c" class="click-tag" @click="router.push(`/devices/${encodeURIComponent(c)}`)">{{c}}</el-tag></template></el-card></div></template>
